import {setupSceneSplitter} from './scene-splitter.js?v=20261025-release1';
export function scenePanels(editor){
 const gizmo=editor.gizmo.toolbar,more=document.createElement('details');more.className='gizmo-options';more.innerHTML='<summary>축 · 부위 · 스냅</summary>';for(const el of [...gizmo.children])if(!el.matches('.gizmo-modes,.scene-quick-transform,.scene-space')&&el.id!=='transformReadout')more.append(el);gizmo.append(more);
 const $=id=>document.getElementById(id),controls=document.querySelector('.scene-controls'),tabs=document.createElement('nav');tabs.className='scene-tabs';tabs.setAttribute('aria-label','3D 속성');
 const groups=[['배경',[$('modelImport'),$('importState'),$('scenePreset').parentElement,$('wireToggle').parentElement]],['인물',[$('addPerson').parentElement,$('personSelect').parentElement,$('pose').parentElement,...['personX','personZ','personY','personRotation','personScale'].map(id=>$(id).parentElement)]],['카메라',[$('fov').parentElement,$('fitModel').parentElement,$('gridToggle').parentElement,$('captureScene')]]];
 controls.prepend(tabs);groups.forEach(([name,els],i)=>{const p=document.createElement('div');p.className='scene-property-group';p.dataset.group=String(i);p.hidden=i!==1;els.forEach(el=>p.append(el));controls.append(p);const b=document.createElement('button');b.textContent=name;b.classList.toggle('active',i===1);b.onclick=()=>{controls.querySelectorAll('.scene-property-group').forEach(el=>el.hidden=el!==p);tabs.querySelectorAll('button').forEach(el=>el.classList.toggle('active',el===b));};tabs.append(b);});
 const views=document.createElement('div');views.className='scene-views';
 for(const [name,dir]of [['정면',[0,0,1]],['측면',[1,0,0]],['뒤',[0,0,-1]],['위',[0,1,.001]]]){const b=document.createElement('button');b.textContent=name;b.onclick=()=>{editor.gizmo.frame();const distance=editor.camera.position.distanceTo(editor.controls.target);editor.camera.position.copy(editor.controls.target).addScaledVector({x:dir[0],y:dir[1],z:dir[2]},distance);editor.controls.update();editor.storeCamera();};views.append(b);}
 const isolate=document.createElement('button');isolate.textContent='배경 잠시 숨김';isolate.title='포즈 편집용 · 컷에는 배경이 그대로 출력됩니다';isolate.onclick=()=>{editor.environment.visible=!editor.environment.visible;isolate.classList.toggle('active',!editor.environment.visible);editor.invalidate();};views.append(isolate);$('sceneView').append(views);
 $('closeScene').textContent='−';$('closeScene').title='3D 창 최소화';$('closeScene').setAttribute('aria-label','3D 창 최소화');
 controls.append($('dockPropsToggle'));setupSceneSplitter(controls);
}
